import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";

function EditArticlePage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  useEffect(() => {
    const fetchArticle = async () => {
      const res = await fetch(`http://127.0.0.1:8000/api/articles/${id}/`);
      const data = await res.json();
      setTitle(data.title);
      setContent(data.content);
    };
    fetchArticle();
  }, [id]);

  const handleUpdate = async () => {
    const token = localStorage.getItem("token");

    const res = await fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ title, content }),
    });

    if (res.ok) {
      alert("✅ Статтю оновлено!");
      navigate("/");
    } else {
      alert("❌ Помилка при оновленні статті");
    }
  };

  return (
    <div className="edit-article-container">
      <h2>Редагування статті</h2>
      <input
        type="text"
        value={title}
        placeholder="Заголовок"
        onChange={(e) => setTitle(e.target.value)}
      />
      <textarea
        value={content}
        placeholder="Текст статті"
        onChange={(e) => setContent(e.target.value)}
      />
      <button onClick={handleUpdate}>💾 Зберегти зміни</button>
    </div>
  );
}

export default EditArticlePage;
